  always @* begin
    if (exp == 5'h1f && mant != 10'h000) out_r = 16'h7e00;
    else if (exp == 5'h1f) out_r = sign ? 16'hfc00 : 16'h7c00;
    else if (sign) out_r = pos_out ^ 16'h8000;
    else out_r = pos_out;
  end
  assign out = out_r;
